#!/usr/bin/env node
// Replace dependencies of a built Storage checkout with throwing stubs, so the Perry compile does not
// bundle them. Local-dev shim, not an upstream candidate: storage-stubs.sh says which packages and why.
//
//   stub-packages.cjs <storage dir> <spec>...
//   stub-packages.cjs <storage dir> --restore
//
// <spec> is one of
//   <package>[/<subpath>]    the file Node resolves for the package, under the "require" and the
//                            "import" condition, becomes a stub exporting every name the built
//                            Storage (dist/, tests excluded) reads from it: capitalised names are
//                            classes whose constructor throws (so `instanceof` keeps working), other
//                            names are functions that throw, `default` is a function that throws
//   <package>=inert         the same, but constructors do not throw (for modules that construct at
//                            load time, like `new Agent()` of undici in the webhook and CDN modules)
//   file:<dist path>=plugin  a built Storage file becomes `export default async () => {}`
//   file:<dist path>=empty   a built Storage file becomes `module.exports = {}`
// Stubs only throw when used, so loading them is harmless. Originals are kept as <file>.stub-orig and
// every run starts from them, which makes it idempotent.
const fs = require('fs')
const path = require('path')
const { execFileSync } = require('child_process')

const root = path.resolve(process.argv[2] || '.')
const specs = process.argv.slice(3)
if (!specs.length) { console.error('usage: stub-packages.cjs <storage dir> <spec>... | --restore'); process.exit(2) }

const ORIG = '.stub-orig'
function* walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name)
    if (e.isDirectory()) { if (e.name !== 'test') yield* walk(p) } else if (p.endsWith('.js') && !p.endsWith('.test.js')) yield p
  }
}
function restore(dir) {
  const walkAll = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name)
      if (e.isDirectory()) walkAll(p)
      else if (p.endsWith(ORIG)) { fs.copyFileSync(p, p.slice(0, -ORIG.length)); fs.unlinkSync(p); console.log('restored', path.relative(root, p.slice(0, -ORIG.length))) }
    }
  }
  walkAll(dir)
}
if (specs[0] === '--restore') { restore(root); process.exit(0) }

const distFiles = [...walk(path.join(root, 'dist'))].map((f) => [f, fs.readFileSync(f, 'utf8')])
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&')
function namesFor(spec) {
  const names = new Set()
  const q = esc(spec)
  for (const [, s] of distFiles) {
    let m
    const bound = new RegExp(`(?:var|const|let)\\s+(\\w+)\\s*=\\s*(?:__toESM\\()?require\\((["'])${q}\\2\\)`, 'g')
    while ((m = bound.exec(s))) {
      const acc = new RegExp(`\\b${m[1]}\\.(\\w+)`, 'g')
      let x
      while ((x = acc.exec(s))) names.add(x[1])
    }
    const destr = new RegExp(`(?:var|const|let)\\s*\\{([^}]*)\\}\\s*=\\s*require\\((["'])${q}\\2\\)`, 'g')
    while ((m = destr.exec(s))) for (const part of m[1].split(',')) { const n = part.split(':')[0].trim(); if (/^\w+$/.test(n)) names.add(n) }
  }
  return [...names].filter((n) => n !== '__esModule')
}
function stubSource(spec, names, esm, inert) {
  const msg = `${spec} is stubbed out in this build`
  const lines = [`// stub for ${spec}, generated by .github/supa/stub-packages.cjs`]
  const fn = (n) => n[0] >= 'A' && n[0] <= 'Z'
    ? (inert ? `class ${n} {}` : `class ${n} { constructor() { throw new Error(${JSON.stringify(msg + ': ' + n)}) } }`)
    : `function ${n}() { throw new Error(${JSON.stringify(msg + ': ' + n)}) }`
  const ids = names.filter((n) => n !== 'default' && /^[A-Za-z_$][\w$]*$/.test(n))
  if (esm) {
    for (const n of ids) lines.push(`export ${fn(n)}`)
    lines.push(`export default function stubbed() { throw new Error(${JSON.stringify(msg)}) }`)
  } else {
    lines.push('"use strict";', "Object.defineProperty(exports, '__esModule', { value: true });")
    for (const n of ids) lines.push(fn(n), `exports.${n} = ${n};`)
    lines.push(`exports.default = function stubbed() { throw new Error(${JSON.stringify(msg)}) };`)
  }
  return lines.join('\n') + '\n'
}
function write(file, content) {
  if (!file.startsWith(root + path.sep)) throw new Error('refusing to write outside the checkout: ' + file)
  if (!fs.existsSync(file + ORIG)) fs.copyFileSync(file, file + ORIG)
  fs.writeFileSync(file, content)
  console.log('stubbed', path.relative(root, file), `(${fs.statSync(file + ORIG).size} -> ${content.length} bytes)`)
}
function pkgIsModule(file) {
  let d = path.dirname(file)
  while (d.startsWith(root)) {
    try { const j = JSON.parse(fs.readFileSync(path.join(d, 'package.json'), 'utf8')); if (j.name) return j.type === 'module' } catch {}
    d = path.dirname(d)
  }
  return false
}

for (const spec of specs) {
  if (spec.startsWith('file:')) {
    const [rel, kind] = spec.slice(5).split('=')
    const file = path.resolve(root, rel)
    if (!fs.existsSync(file + ORIG) && !fs.existsSync(file)) throw new Error('no such file ' + rel)
    if (fs.existsSync(file + ORIG)) fs.copyFileSync(file + ORIG, file)
    if (kind === 'plugin') write(file, '"use strict";\nObject.defineProperty(exports, "__esModule", { value: true });\nexports.default = async function stubbedPlugin() {};\n')
    else if (kind === 'empty') write(file, '"use strict";\nmodule.exports = {};\n')
    else throw new Error('unknown kind in ' + spec)
    continue
  }
  const [pkg, mode] = spec.split('=')
  const names = namesFor(pkg)
  const files = new Map()
  try { files.set(require.resolve(pkg, { paths: [root] }), false) } catch {}
  try {
    const u = execFileSync(process.execPath, ['--input-type=module', '-e', 'console.log(import.meta.resolve(process.argv[1]))', pkg], { cwd: root, encoding: 'utf8' }).trim()
    if (u.startsWith('file://')) { const f = new URL(u).pathname; files.set(f, files.has(f) ? files.get(f) : true) }
  } catch {}
  if (!files.size) { console.error('cannot resolve', pkg); process.exit(1) }
  for (const [file] of files) {
    if (fs.existsSync(file + ORIG)) fs.copyFileSync(file + ORIG, file)
    write(file, stubSource(pkg, names, file.endsWith('.mjs') || (!file.endsWith('.cjs') && pkgIsModule(file)), mode === 'inert'))
  }
  console.log(`  ${pkg}${mode ? '=' + mode : ''}: names=${names.join(',') || '-'}`)
}
